import logging
import re
import sys
from concurrent.futures import ThreadPoolExecutor, TimeoutError
from os import getpid, kill, listdir, path

from moler.config import load_config
from moler.device import DeviceFactory

from ta_logcollector.settings import lc_info
from ta_logcollector.utils.common import run_remote_cmd, vm_host


def _get_lc_ver(output: str) -> str:
    """
    Fetch LC version (major.minor.patch) from string output

    :param output: string which can contain version
    """
    match = re.search(r"([\d+.]+)", output)
    return str(match.group(1)) if match else ""


def _check_ver_on_host(logger: logging.Logger, data: vm_host) -> tuple[str, str]:
    """
    Gets currently installed version of ta_logcollector and returns tuple of host address and version

    :param logger: network logger
    :param data: namedtuple with addr, usr, passwd of remote host
    """
    try:
        stdout, stderr = run_remote_cmd(
            logger, data.usr, data.addr, data.passwd, cmd=f"{sys.executable} -m pip list | grep logcollector"
        )
        lc_ver = _get_lc_ver(stdout)
    except AttributeError as e:
        lc_ver, stderr = "SSH ERROR", e
    if stderr:
        logger.error(stderr)
    return lc_info(data.addr, lc_ver)


def check_logcollector_version_on_hosts(logger: logging.Logger, hosts: dict) -> list[lc_info]:
    """
    Check logcollector version on provided hosts and returns list of dictionaries with host and version

    :param logger: network logger
    :param hosts: dictionary with information about discovered hosts
    :return: list of tuples with address and version of logcollector per host
    """
    with ThreadPoolExecutor(max_workers=len(hosts)) as executor:
        futures = [(executor.submit(_check_ver_on_host, logger, data), data.addr) for name, data in hosts.items()]
        outputs = []
        for future, host_addr in futures:
            try:
                outputs.append(future.result(45))
            except TimeoutError:
                outputs.append(lc_info(host_addr, ""))
    return outputs


def seppuku(logger: logging.Logger) -> None:
    """
    LC decide to make harakiri process of gui

    :param logger: network logger
    """
    pid = getpid()
    logger.debug(f"LC GUI made seppuku pid: {pid}")
    kill(pid, 9)


def get_latest_logs_directory(logger: logging.Logger, tmp_log_dir: str = "/tmp/logcollector") -> str:
    """
    Get last modified directory name from specified location

    :param logger: network logger
    :param tmp_log_dir: directory where to check for last modified subdirectory
    :return: last modified directory
    """
    latest_subdir = ""
    try:
        all_subdirs = [path.join(tmp_log_dir, d) for d in listdir(tmp_log_dir) if path.isdir(path.join(tmp_log_dir, d))]
        latest_subdir = max(all_subdirs, key=path.getmtime)
        return latest_subdir
    except OSError:
        logger.debug(f"{tmp_log_dir} does not exist")
    except ValueError:
        logger.debug(f"{tmp_log_dir} does not contain any directories")
    finally:
        return latest_subdir


