def reboot_enb(logger: logging.Logger, vmhost: vm_host) -> str:
    """
    Reboot eNb connected to Virtual Machine.

    :param logger: network logger
    :param vmhost: dict of VM configuration
    :return: reboot command output
    """
    host = vmhost.addr
    moler_cfg = generate_moler_config(vmhost)
    logger.debug(f"moler config for {host}: {moler_cfg}")
    load_config(config=moler_cfg)
    device = DeviceFactory.get_device(f"{host}_enb")
    device.goto_state(state="FCT")
    reboot_output = device.get_cmd(cmd_name="reboot")()
    logger.debug(f"reboot eNB {host} output: {reboot_output}")
    return reboot_output


def check_tl_config_for_ue_sim(taf_tl_config):
    for simulator in ["cus", "iphy", "airphone"]:
        for ue in taf_tl_config.ues:
            if type(ue).__name__.lower() == simulator:
                yield simulator, True
                break
